# RotatedMercator generality: load a synthetic rotated_mercator file, save, reload.
import sys
sys.path.insert(0, 'source/lib')
import subprocess, tempfile, os, warnings
warnings.simplefilter('ignore')
import iris, iris.coord_systems as ics

cdl = """
netcdf test {
dimensions:
    y = 2 ; x = 3 ;
variables:
    double phenom(y, x) ;
        phenom:standard_name = "air_temperature" ;
        phenom:units = "K" ;
        phenom:grid_mapping = "grid" ;
    double yco(y) ;
        yco:axis = "Y" ; yco:units = "m" ;
        yco:standard_name = "projection_y_coordinate" ;
    double xco(x) ;
        xco:axis = "X" ; xco:units = "m" ;
        xco:standard_name = "projection_x_coordinate" ;
    int grid ;
        grid:grid_mapping_name = "rotated_mercator" ;
        grid:latitude_of_projection_origin = 52.0 ;
        grid:longitude_of_projection_origin = -3.0 ;
        grid:scale_factor_at_projection_origin = 0.9996 ;
        grid:earth_radius = 6371000.0 ;
data:
    yco = 100., 200. ;
    xco = 10., 20., 30. ;
}
"""
with tempfile.TemporaryDirectory() as td:
    cdl_path = os.path.join(td, 't.cdl'); nc_path = os.path.join(td, 't.nc')
    open(cdl_path, 'w').write(cdl)
    from netCDF4 import Dataset
    # ncgen may not exist; build with python instead
    ds = Dataset(nc_path, 'w')
    ds.createDimension('y', 2); ds.createDimension('x', 3)
    p = ds.createVariable('phenom', 'f8', ('y','x'))
    p.standard_name='air_temperature'; p.units='K'; p.grid_mapping='grid'
    y = ds.createVariable('yco','f8',('y',)); y.axis='Y'; y.units='m'; y.standard_name='projection_y_coordinate'; y[:] = [100.,200.]
    x = ds.createVariable('xco','f8',('x',)); x.axis='X'; x.units='m'; x.standard_name='projection_x_coordinate'; x[:] = [10.,20.,30.]
    g = ds.createVariable('grid','i4')
    g.grid_mapping_name='rotated_mercator'
    g.latitude_of_projection_origin=52.0
    g.longitude_of_projection_origin=-3.0
    g.scale_factor_at_projection_origin=0.9996
    g.earth_radius=6371000.0
    ds.close()
    cube = iris.load_cube(nc_path)
    cs = cube.coord_system()
    print('loaded:', cs)
    assert isinstance(cs, ics.RotatedMercator), type(cs)
    assert cs.azimuth == 90.0
    out = os.path.join(td, 'out.nc')
    iris.save(cube, out)
    cube2 = iris.load_cube(out)
    print('reloaded:', cube2.coord_system())
    assert cube2.coord_system() == cs
    # cartopy transform works
    proj = cs.as_cartopy_projection()
    import cartopy.crs as ccrs
    pts = ccrs.PlateCarree().transform_points(proj, *__import__('numpy').meshgrid([10.,20.],[100.,200.]))
    print('transform sample ok:', pts.shape)
print('OK')
